import React from "react";
import { Link } from "gatsby";

import type { NoticeTemplate } from "../../templates/notice/default-template";
import SectionTitle from "../../primitives/section-title/section-title";

export type NoticeAction = {
  label: string;
  /** Internal route. These pages only ever point back into the site. */
  to: string;
  /** Matches the site button system: the gold CTA or the outlined secondary. */
  variant: "gold" | "outline";
};

export type NoticePageProps = {
  /** Structure, style and colour. Supplied by the caller's config. */
  template: NoticeTemplate;
  /** The oversized outlined word — "404", "COMING SOON". */
  backgroundText?: string;
  title: string;
  description?: string;
  actions?: NoticeAction[];
};

/**
 * The shared body of the Coming Soon and Page Not Found pages.
 *
 * Presentation only, and deliberately says nothing about which state it is
 * showing: the two pages mean different things to a visitor and each supplies
 * its own words, but they are the same composition and should not drift apart.
 *
 * The heading is the site's SectionTitle at h1 — these pages are the only ones
 * where it carries the document's single top-level heading, since there is no
 * other content to outrank it.
 */
export default function NoticePage({
  template,
  backgroundText,
  title,
  description,
  actions = [],
}: NoticePageProps) {
  return (
    <section className={template.rootClass}>
      <style>{template.css}</style>

      <span className={`${template.rootClass}__backdrop`} aria-hidden="true" />

      <div className={`${template.rootClass}__inner`}>
        <SectionTitle
          backgroundText={backgroundText}
          title={title}
          description={description}
          align="center"
          as="h1"
        />

        {actions.length ? (
          <div className={`${template.rootClass}__actions`}>
            {actions.map((action) => (
              <Link
                key={action.to}
                to={action.to}
                className={`kr-btn kr-btn--${action.variant}`}
              >
                {action.label}
              </Link>
            ))}
          </div>
        ) : null}
      </div>
    </section>
  );
}
