import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import NotFoundPage from "../components/NotFoundPage";

/**
 * The site's fallback route.
 *
 * A root splat, so it claims any address no more specific page owns. Gatsby
 * ranks routes by specificity, so this sits behind every real page — `/`,
 * `/properties`, `/apply`, each `/properties/:slug`, and the dashboard's own
 * splat at `/dashboard/*` — and only picks up what is left, at any depth.
 *
 * Keep the filename. Renaming it to 404.tsx would hand these addresses back to
 * Gatsby's built-in handling and lose the client-side match, and renaming it to
 * [id].tsx would narrow it to a single URL segment, so `/one/two/three` would
 * stop resolving here.
 */
export default function CatchAllPage(_props: PageProps) {
  return <NotFoundPage />;
}

export const Head: HeadFC = () => (
  <>
    <title>Page Not Found | Kelley Road Property Management</title>
    <meta
      name="description"
      content="The page you were looking for could not be found. Browse available Kelley Road properties or return to the homepage."
    />
    {/* Not a content page: keep it out of the index, but let the crawler
        follow the links back into the site. */}
    <meta name="robots" content="noindex, follow" />
  </>
);
