// Styling for the notice pages — Coming Soon and Page Not Found.
//
// Both states share this one sheet because they are the same composition: a
// centred column, the site's oversized outlined word behind it, and a pair of
// actions. What differs between them is content, not treatment, so forking the
// CSS would only let the two drift apart.
//
// The heading itself is not styled here. It is the site's SectionTitle, which
// already owns the outlined word, the gold rule and the entrance — reaching
// past it to restyle the type would be a second heading system.

import brand from "../brand";

export type NoticeTemplate = {
  css: string;
  rootClass: string;
};

const color = {
  background: brand.colors.background,
  /* The architectural detail: hairlines at the edge of visibility, and a wash
     that lifts the centre off the white. Both decorative, both aria-hidden. */
  rule: "rgba(31, 35, 40, 0.05)",
  wash: "rgba(200, 159, 91, 0.05)",
  focus: brand.colors.accent,
};

const layout = {
  maxWidth: 1280,
  /* Tall enough that the footer stays below the fold on a laptop, capped so it
     does not become a void on a tall monitor. */
  minHeight: "clamp(460px, 66vh, 760px)",
  minHeightSmall: "clamp(460px, 66svh, 760px)",
  minHeightMobile: "clamp(380px, 56vh, 560px)",
  ruleGap: 148,
};

const spacing = {
  gutter: 40,
  gutterCompact: 20,
  sectionTop: 96,
  sectionBottom: 112,
  sectionTopCompact: 64,
  sectionBottomCompact: 76,
  actionsGap: 44,
  actionsGapCompact: 32,
  buttonGap: 14,
};

const timing = {
  /* Starts after SectionTitle has moved, so the page resolves top to bottom
     rather than everything arriving at once. */
  actions: 640,
  actionsDelay: 420,
};

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-notice {
  position: relative;
  display: flex;
  align-items: center;
  min-height: ${layout.minHeight};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  background: ${color.background};
  overflow: hidden;
  isolation: isolate;
}
@supports (height: 1svh) {
  .kr-notice { min-height: ${layout.minHeightSmall}; }
}

/* Architectural detail rather than photography: evenly spaced hairlines and a
   soft centre wash, both barely there. Nothing to read, nothing to announce. */
.kr-notice__backdrop {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    radial-gradient(60% 55% at 50% 42%, ${color.wash} 0%, transparent 70%),
    repeating-linear-gradient(
      to right,
      ${color.rule} 0 1px,
      transparent 1px ${layout.ruleGap}px
    );
}

.kr-notice__inner {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}

.kr-notice__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: ${spacing.buttonGap}px;
  margin-top: ${spacing.actionsGap}px;
  animation: kr-notice-rise ${timing.actions}ms ${ease} ${timing.actionsDelay}ms both;
}

@keyframes kr-notice-rise {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: none; }
}


@media (max-width: 760px) {
  .kr-notice {
    min-height: ${layout.minHeightMobile};
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-notice__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-notice__actions { margin-top: ${spacing.actionsGapCompact}px; }
  /* Side by side they would each be too narrow to read comfortably. */
  .kr-notice__actions .kr-btn { flex: 1 1 100%; }
}

@media (prefers-reduced-motion: reduce) {
  /* The actions are already in their final state without the animation, so
     switching it off shows the finished page rather than nothing. */
  .kr-notice__actions { animation: none; }
}
`;

const template: NoticeTemplate = {
  css,
  rootClass: "kr-notice",
};

export default template;
